        intervals.append((L, R))

    mask_all = (1 << B) - 1

    G = [0] * B
    row0 = 0
    for k in range(A - 1, B):
        row0 |= (1 << k)
    G[0] = row0
    for k in range(1, B):
        G[k] = 1 << (k - 1)

    def mat_mul(X, Y):
        Z = [0] * B
        for i in range(B):
            xi = X[i]
            zi = 0
            j = 0
            while xi:
